export const TYPES=['草','炎','水','雷','岩','風','光','影'];
const MOVE_NAMES=[
 ['若葉カッター','大樹の一撃','芽吹きの祈り','絡みつくツタ','葉の結界','生命の根','森の集中','毒花の粉'],
 ['火の粉','紅蓮ブレス','熾火の再生','煙幕フレア','炎の壁','吸熱の牙','燃える闘志','残火の呪い'],
 ['水しぶき','大波クラッシュ','清流の癒し','泡の足かせ','水鏡の盾','吸水の渦','静かな水面','深海の毒'],
 ['電光スパーク','雷鳴ストライク','帯電の再生','磁力の縛り','電磁バリア','吸電の爪','雷雲チャージ','放電の痺れ'],
 ['小石ショット','巨岩プレス','鉱脈の再生','砂塵の縛り','岩盤の盾','鉱石の吸収','大地の構え','崩落の傷'],
 ['そよ風カッター','暴風の翼','癒しの風','逆風の縛り','風のヴェール','吸気の翼','追い風の集中','裂風の傷'],
 ['星光ショット','暁の閃光','月光の癒し','眩光の縛り','光の結界','星の吸収','灯台の祈り','星屑の刻印'],
 ['影の爪','深淵の牙','夜の再生','黒霧の縛り','影の衣','魂の吸収','闇の集中','月影の呪い']
];
const MOVE_ROLES=[
 {kind:'hit',cost:0,power:1,description:'属性攻撃。気力を1回復。'},
 {kind:'hit',cost:2,power:1.6,description:'気力2で強力な属性攻撃。'},
 {kind:'heal',cost:2,power:0,description:'最大HPの約28%を回復。'},
 {kind:'weaken',cost:1,power:.65,description:'攻撃し、相手の威力を3行動の間25%下げる。'},
 {kind:'shield',cost:1,power:0,description:'このターンの被ダメージを60%減らす。'},
 {kind:'drain',cost:2,power:1.05,description:'与えたダメージの半分を吸収。'},
 {kind:'focus',cost:1,power:0,description:'次の3ターン、攻撃の威力を35%上げる。'},
 {kind:'poison',cost:2,power:.75,description:'攻撃後3ターン、相手の最大HPの6%を削る。'}
];
export const MOVES=MOVE_NAMES.flatMap((names,type)=>names.map((name,slot)=>({id:type*8+slot,type,name,level:[1,3,6,9,12,16,22,28][slot],...MOVE_ROLES[slot]})));
export function learnedMoves(m){return MOVES.filter(v=>v.type===SPECIES[m.id].type&&v.level<=m.level);}
export function equippedMoves(m){if(Array.isArray(m.moves))return m.moves.map(id=>MOVES[id]);const learned=learnedMoves(m);return learned.length<=4?learned:[...learned.slice(0,2),...learned.slice(-2)];}
export function equipMove(m,id,slot){if(!Number.isInteger(slot)||slot<0||slot>3||!learnedMoves(m).some(v=>v.id===id))return false;const list=equippedMoves(m).map(v=>v.id);if(list.includes(id)||slot>list.length)return false;list[slot]=id;m.moves=list;return true;}
export function migrateMoves(s,b=null){for(const m of [...s.party,...s.box,...(b?[b.enemy,...(b.roster||[])]:[])])if(m.moves===undefined)m.moves=equippedMoves(m).map(v=>v.id);return s;}
const names=['コノハル','ヒノトカ','ミズコ','ピカリト','モリシカ','エンリュウ','ナミアザラ','ライガ','ゴロマル','ソラフク','キラモス','カゲネコ','イワドン','カゼグリフ','ルミドラ','ヨルヒョウ'];
const types=[0,1,2,3,0,1,2,3,4,5,6,7,4,5,6,7];
const descriptions=['耳に若葉が芽吹く森の案内役。','しっぽの火で仲間をあたためる。','澄んだ川で小石を集める。','雷雲の下でも元気に跳ねる。','森の古い記憶を守る角を持つ。','勇気に応えて炎の翼を広げる。','潮の流れを歌声で導く。','嵐を駆ける金色の狩人。','石ころを背負ったのんびり屋。','風の便りを運ぶ夜の見張り。','羽に星明かりを蓄える。','月影を渡り歩く小さな猫。','島の大地を支える古い守護者。','雲を切り裂く誇り高い翼。','島の灯台と同じ光を放つ。','夜を守る静かな王者。'];
export const SPECIES=names.map((name,id)=>({id,name,type:types[id],evolve:({0:4,1:5,2:6,3:7,8:12,9:13,10:14,11:15})[id],base:([4,5,6,7,12,13,14,15].includes(id)?20:10),description:descriptions[id]}));
export const REGIONS=[{name:'こもれびの里',type:0,pool:[0,8,9],level:4,color:'#6fac55',boss:4,bossName:'森の番人 ミナ',hint:'北西の森でミナに挑もう。',challenge:'森の歩調は、仲間を信じる心から。炎属性の仲間と気力を整えて、コノハルとモリシカの連携を越えてみて。',rematch:'森は何度でも芽吹くもの。きみの仲間がどれだけ育ったか、もう一度見せて！'},{name:'潮風の浜',type:2,pool:[2,9,10],level:8,color:'#69bbc7',boss:6,bossName:'潮の番人 ナギ',hint:'北東の浜でナギに挑もう。',challenge:'波に逆らうより、流れを読むんだ。草か雷属性の仲間なら、ミズコとナミアザラの水の守りを崩せるよ。',rematch:'前よりいい波を起こせそうだね。潮風の浜でもう一度勝負しよう！'},{name:'火花の高原',type:1,pool:[1,3,8],level:12,color:'#ba865c',boss:5,bossName:'火の番人 アカネ',hint:'南西の高原でアカネに挑もう。',challenge:'熱さだけで突っ込むと火傷するよ。三ターンごとの奥義は「守る」で受けて、雷と炎の連携を破ってみな！',rematch:'その目、まだ燃えてるね！ 高原の火花より熱い再戦にしよう！'},{name:'星影の森',type:7,pool:[11,10,3],level:16,color:'#6e729e',boss:15,bossName:'夜の番人 ヨル',hint:'南東の森でヨルに挑もう。',challenge:'夜は光を隠さず、強く映す。光属性は影に強いけれど互いに大ダメージ。交代の時を見極めて。',rematch:'影は同じ形を二度と見せない。新しい仲間と来たなら、また夜を越えてみせて。'}];
export function rng(s){s.seed=(Math.imul(s.seed,1664525)+1013904223)>>>0;return s.seed/4294967296;}
export function createMonster(id,level=3,rare=false){const m={id,level,xp:0,hp:1,energy:4,rare};m.hp=maxHP(m);m.moves=equippedMoves(m).map(v=>v.id);return m;}
export function maxHP(m){return 22+m.level*5+SPECIES[m.id].base;}
export function power(m){return 7+m.level*2+SPECIES[m.id].base*.5;}
export function effectiveness(a,b){const strong={0:[2,4],1:[0,5],2:[1,4],3:[2,5],4:[1,3],5:[0,4],6:[7],7:[6]};if(strong[a].includes(b))return 1.6;if(strong[b].includes(a))return .65;return 1;}
export function makeState(starter=0){return {version:1,seed:Date.now()>>>0,x:8,y:8,dir:2,steps:0,region:0,party:[createMonster(starter)],box:[],seen:[starter],caught:[starter],badges:[],coins:150,balls:12,potions:5,wins:0,captures:0,quest:0,ended:false,playSeconds:0,created:Date.now(),postgame:{medals:0,bestFloor:0,runs:0,tower:null}};}
export function migratePostgame(s){if(s.postgame===undefined)s.postgame={medals:0,bestFloor:0,runs:0,tower:null};return s;}
export function heal(s){[...s.party,...s.box].forEach(m=>{m.hp=maxHP(m);m.energy=4;});}
export function addXP(m,amount){const events=[];m.xp+=amount;while(m.level<40&&m.xp>=m.level*12){m.xp-=m.level*12;m.level++;for(const v of learnedMoves(m).filter(v=>v.level===m.level)){events.push(`${SPECIES[m.id].name}は「${v.name}」を覚えた！`);if(Array.isArray(m.moves)&&m.moves.length<4&&!m.moves.includes(v.id))m.moves.push(v.id);}m.hp=Math.min(maxHP(m),m.hp+8);events.push(`${SPECIES[m.id].name}はLv.${m.level}になった！`);if(m.level>=10&&SPECIES[m.id].evolve!==undefined){m.id=SPECIES[m.id].evolve;m.hp=maxHP(m);events.push(`${SPECIES[m.id].name}へ進化した！`);}}return events;}
export function active(s){return s.party.findIndex(m=>m.hp>0);}
export function encounter(s,region,boss=false,final=false){const r=REGIONS[region];const id=final?14:boss?r.boss:r.pool[Math.floor(rng(s)*r.pool.length)];const level=final?25:boss?r.level+4:r.level+Math.floor(rng(s)*3);const enemy=createMonster(id,level,!boss&&rng(s)<.025);if(!s.seen.includes(id))s.seen.push(id);const roster=final?[createMonster(15,24),enemy]:boss?[enemy]:[];const first=final?createMonster(12,23):boss?createMonster([0,2,3,11][region],r.level+2):enemy;return {enemy:first,roster,totalEnemies:boss?(final?3:2):1,region,boss,final,turn:0,active:Math.max(0,active(s)),log:[final?'灯台の守護竜 ルミドラが姿を現した！':boss?`${r.bossName}が勝負を挑んできた！`:`野生の${SPECIES[id].name}${enemy.rare?'（星色）':''}が現れた！`],result:null,guard:false};}
function towerFoe(floor,slot){return createMonster((floor*5+slot*7)%SPECIES.length,Math.min(40,17+floor+Math.floor(slot/2)));}
export function towerEncounter(s){const run=s.postgame?.tower;if(!s.ended||!run||run.waiting)return null;const count=run.floor%5===0?3:2,foes=Array.from({length:count},(_,i)=>towerFoe(run.floor,i));return {enemy:foes[0],roster:foes.slice(1),totalEnemies:count,region:run.floor%4,boss:true,final:false,tower:true,towerFloor:run.floor,turn:0,active:Math.max(0,active(s)),log:[`星巡りの塔 ${run.floor}階。${count}体の試練が始まる！`],result:null,guard:false};}
export function startTower(s){migratePostgame(s);if(!s.ended||s.postgame.tower)return null;heal(s);s.postgame.tower={floor:1,pending:0,waiting:false};return towerEncounter(s);}
export function continueTower(s,choice='next'){migratePostgame(s);const run=s.postgame.tower;if(!s.ended||!run||!run.waiting)return null;const checkpoint=run.floor%5===0;if(checkpoint&&!['heal','bonus'].includes(choice)||!checkpoint&&choice!=='next')return null;if(choice==='heal')heal(s);if(choice==='bonus')run.pending+=5;run.floor++;run.waiting=false;return towerEncounter(s);}
export function retireTower(s){migratePostgame(s);const run=s.postgame.tower;if(!run?.waiting)return false;s.postgame.medals+=run.pending;s.postgame.runs++;s.postgame.tower=null;return true;}
export function buyResearch(s,item){migratePostgame(s);const offers={potion:{cost:6,key:'potions',amount:3},ball:{cost:8,key:'balls',amount:5}},offer=offers[item];if(!offer||s.postgame.medals<offer.cost)return false;s.postgame.medals-=offer.cost;s[offer.key]+=offer.amount;return true;}
function damage(s,a,b,heavy=false){return Math.max(1,Math.round(power(a)*(heavy?1.6:1)*effectiveness(SPECIES[a.id].type,SPECIES[b.id].type)*(.85+rng(s)*.3)));}
function finish(s,b,result){b.result=result;if(b.tower){const run=s.postgame.tower;if(result==='win'){const reward=2+Math.floor(b.towerFloor/5);s.wins++;run.pending+=reward;run.waiting=true;s.postgame.bestFloor=Math.max(s.postgame.bestFloor,b.towerFloor);for(const m of s.party)b.log.push(...addXP(m,Math.round(b.enemy.level*7*(m.hp>0?1:.5))));b.log.push(`塔の試練を突破！ 研究メダル候補 +${reward}（撤退時に確定）。`);}else if(result==='lose'){const lost=run?.pending||0;s.postgame.tower=null;heal(s);b.log.push(`塔から帰還した。未確定の研究メダル ${lost}枚を失った。`);}return;}if(result==='win'){const earned=b.boss?180:28+b.enemy.level*4;s.coins+=earned;s.wins++;b.log.push(`勝利！ ${earned}コインを手に入れた。`);for(const m of s.party)b.log.push(...addXP(m,Math.round(b.enemy.level*(b.boss?18:9)*(m.hp>0?1:.5))));for(const m of s.party){if(!s.caught.includes(m.id))s.caught.push(m.id);if(!s.seen.includes(m.id))s.seen.push(m.id);}if(b.boss&&!b.final&&!s.badges.includes(b.region)){s.badges.push(b.region);s.balls+=8;s.potions+=3;b.log.push('紋章を手に入れた！ 次のエリアへ進める。');}if(b.final){s.ended=true;b.log.push('四つの紋章が輝き、ルミナ島の灯台に光が戻った！');}}else if(result==='lose'){s.coins=Math.max(0,s.coins-40);heal(s);s.x=8;s.y=8;s.region=0;b.log.push('仲間が全員倒れた……里の診療所で回復した。');}}

function effects(b){return b.effects??(b.effects={ally:{},enemy:{}});}
function scaledDamage(s,b,a,target,multiplier,type,side){const e=effects(b)[side];return Math.max(1,Math.round(damage(s,a,target,false)*multiplier*(effectiveness(type,SPECIES[target.id].type)/effectiveness(SPECIES[a.id].type,SPECIES[target.id].type))*(e.focus?1.35:1)*(e.weaken?.75:1)));}
function executeMove(s,b,a,target,v,side){const own=effects(b)[side],other=effects(b)[side==='ally'?'enemy':'ally'];a.energy=v.cost?a.energy-v.cost:Math.min(4,a.energy+1);b.log.push(`${SPECIES[a.id].name}の「${v.name}」！`);
 if(v.kind==='heal'){const n=Math.min(maxHP(a)-a.hp,Math.round(maxHP(a)*.28));a.hp+=n;b.log.push(`HPが${n}回復した。`);return;}
 if(v.kind==='focus'){own.focus=4;b.log.push('集中した！ 次の3ターンの攻撃が強くなる。');return;}
 if(v.kind==='shield'){own.shield=1;b.log.push('結界でこのターンのダメージを減らす。');return;}
 let d=scaledDamage(s,b,a,target,v.power,v.type,side);if(other.shield)d=Math.max(1,Math.round(d*.4));if(side==='enemy'&&b.guard)d=Math.max(1,Math.round(d*.4));d=Math.min(target.hp,d);target.hp-=d;b.log.push(`${d}ダメージ${effectiveness(v.type,SPECIES[target.id].type)>1?'・効果抜群！':''}。`);
 if(v.kind==='drain'){const n=Math.min(maxHP(a)-a.hp,Math.ceil(d*.5));a.hp+=n;b.log.push(`HPを${n}吸収した。`);}
 if(v.kind==='weaken'&&target.hp>0){other.weaken=3;b.log.push('相手の威力が下がった。');}
 if(v.kind==='poison'&&target.hp>0){other.poison=3;b.log.push('相手に継続ダメージの印を残した。');}
}
function defeatedEnemy(s,b){if(b.enemy.hp>0)return false;if(b.roster?.length){b.log.push(`${SPECIES[b.enemy.id].name}を倒した！`);b.enemy=b.roster.shift();effects(b).enemy={};if(!s.seen.includes(b.enemy.id))s.seen.push(b.enemy.id);b.log.push(`次の相手、${SPECIES[b.enemy.id].name}が戦場へ！`);}else finish(s,b,'win');return true;}
function tickEffects(s,b,m){const e=effects(b);for(const [side,mon] of [['ally',m],['enemy',b.enemy]]){if(e[side].poison&&mon.hp>0){const d=Math.min(mon.hp,Math.max(1,Math.round(maxHP(mon)*.06)));mon.hp-=d;b.log.push(`${SPECIES[mon.id].name}は印で${d}ダメージ。`);}for(const key of ['poison','weaken','focus','shield'])if(e[side][key])e[side][key]--;}}
function settleTurn(s,b,m){tickEffects(s,b,m);b.guard=false;b.turn++;if(m.hp===0){b.log.push(`${SPECIES[m.id].name}は倒れた。`);const next=active(s);if(next<0){finish(s,b,'lose');return;}b.active=next;effects(b).ally={};b.log.push(`${SPECIES[s.party[next].id].name}が戦場へ！`);}defeatedEnemy(s,b);}
export function act(s,b,action,index){
 if(b.result)return [];if(b.log.length>450)b.log.splice(0,b.log.length-450);const before=b.log.length;let m=s.party[b.active];
 if(action==='switch'){if(!s.party[index]||s.party[index].hp<=0||index===b.active)return [];b.active=index;m=s.party[index];effects(b).ally={};b.log.push(`${SPECIES[m.id].name}に交代！`);}
 else if(action==='potion'){if(s.potions<1){b.log.push('回復薬がない。');return b.log.slice(before);}if(m.hp===maxHP(m)){b.log.push('HPは満タンだ。');return b.log.slice(before);}s.potions--;m.hp=Math.min(maxHP(m),m.hp+50);b.log.push('回復薬でHPを50回復！');}
 else if(action==='capture'){if(b.boss){b.log.push('番人の仲間は捕獲できない。');return b.log.slice(before);}if(!s.balls){b.log.push('捕獲クリスタルがない。');return b.log.slice(before);}s.balls--;const chance=.2+.68*(1-b.enemy.hp/maxHP(b.enemy));if(rng(s)<chance){const c={...b.enemy,moves:equippedMoves(b.enemy).map(v=>v.id),hp:maxHP(b.enemy),energy:4};(s.party.length<6?s.party:s.box).push(c);s.captures++;if(!s.caught.includes(c.id))s.caught.push(c.id);b.log.push(`${SPECIES[c.id].name}が仲間になった！${s.party.length===6?' 手持ち・ボックスを確認しよう。':''}`);b.result='capture';return b.log.slice(before);}b.log.push('クリスタルから飛び出した！');}
 else if(action==='run'){if(b.boss){b.log.push('この勝負からは逃げられない。');return b.log.slice(before);}if(rng(s)<.85){b.result='run';b.log.push('無事に逃げ切った。');return b.log.slice(before);}b.log.push('逃げられなかった！');}
 else if(action==='guard'){b.guard=true;m.energy=Math.min(4,m.energy+2);b.log.push('身を守って気力を2回復。');}
 else if(action==='move'){const v=equippedMoves(m).find(v=>v.id===index);if(!v)return [];if(m.energy<v.cost){b.log.push('気力が足りない。「守る」で回復しよう。');return b.log.slice(before);}if(v.kind==='heal'&&m.hp===maxHP(m)){b.log.push('HPは満タンだ。');return b.log.slice(before);}executeMove(s,b,m,b.enemy,v,'ally');if(b.enemy.hp===0){settleTurn(s,b,m);return b.log.slice(before);}}
 else if(action==='attack'||action==='skill'){if(action==='skill'&&m.energy<2){b.log.push('気力が足りない。「守る」で回復しよう。');return b.log.slice(before);}const heavy=action==='skill';m.energy=heavy?m.energy-2:Math.min(4,m.energy+1);let d=scaledDamage(s,b,m,b.enemy,heavy?1.6:1,SPECIES[m.id].type,'ally');if(effects(b).enemy.shield)d=Math.max(1,Math.round(d*.4));b.enemy.hp=Math.max(0,b.enemy.hp-d);const eff=effectiveness(SPECIES[m.id].type,SPECIES[b.enemy.id].type);b.log.push(`${SPECIES[m.id].name}の${heavy?TYPES[SPECIES[m.id].type]+'の奥義':'攻撃'}！ ${d}ダメージ${eff>1?'・効果抜群！':eff<1?'・相性が悪い…':''}`);if(b.enemy.hp===0){settleTurn(s,b,m);return b.log.slice(before);}}
 else return [];
 const heavy=b.turn%3===2,enemy=b.enemy,choices=equippedMoves(enemy).filter(v=>v.cost<=enemy.energy);
 const healing=choices.find(v=>v.kind==='heal'&&enemy.hp<maxHP(enemy)*.3);
 const damaging=choices.filter(v=>v.power>0&&v.cost>0);
 const chosen=healing||(heavy&&damaging.length?damaging[Math.floor(b.turn/3)%damaging.length]:null);
 if(chosen)executeMove(s,b,enemy,m,chosen,'enemy');
 else {enemy.energy=Math.min(4,enemy.energy+1);let d=scaledDamage(s,b,enemy,m,heavy?1.6:1,SPECIES[enemy.id].type,'enemy');if(b.guard||effects(b).ally.shield)d=Math.max(1,Math.round(d*.4));m.hp=Math.max(0,m.hp-d);b.log.push(`${SPECIES[enemy.id].name}の${heavy?'奥義':'攻撃'}！ ${d}ダメージ。`);}
 settleTurn(s,b,m);return b.log.slice(before);
}
function validPostgame(p){if(p===undefined)return true;if(!p||!Number.isInteger(p.medals)||p.medals<0||p.medals>1e10||!Number.isInteger(p.bestFloor)||p.bestFloor<0||p.bestFloor>999||!Number.isInteger(p.runs)||p.runs<0||p.runs>1e10)return false;const t=p.tower;return t===null||!!t&&Number.isInteger(t.floor)&&t.floor>=1&&t.floor<=999&&Number.isInteger(t.pending)&&t.pending>=0&&t.pending<=1e10&&typeof t.waiting==='boolean';}
export function validState(v){if(!v||!Number.isInteger(v.quest)||v.quest<0||v.quest>3||typeof v.ended!=='boolean'||v.version!==1||!Array.isArray(v.party)||!v.party.length||v.party.length>6||!Array.isArray(v.box)||v.box.length>500||!validPostgame(v.postgame))return false;for(const key of ['x','y','steps','region','coins','balls','potions','wins','captures','seed','playSeconds'])if(!Number.isFinite(v[key])||v[key]<0||v[key]>1e10)return false;if(v.x>=48||v.y>=36||v.region>3||!Array.isArray(v.badges)||v.badges.some(x=>!Number.isInteger(x)||x<0||x>3)||new Set(v.badges).size!==v.badges.length)return false;for(const key of ['caught','seen'])if(!Array.isArray(v[key])||v[key].some(x=>!Number.isInteger(x)||!SPECIES[x]))return false;return [...v.party,...v.box].every(m=>Number.isInteger(m.id)&&SPECIES[m.id]&&Number.isInteger(m.level)&&m.level>=1&&m.level<=40&&Number.isFinite(m.hp)&&m.hp>=0&&m.hp<=maxHP(m)&&Number.isFinite(m.xp)&&m.xp>=0&&Number.isFinite(m.energy)&&m.energy>=0&&m.energy<=4&&(m.moves===undefined||(Array.isArray(m.moves)&&m.moves.length>=1&&m.moves.length<=4&&new Set(m.moves).size===m.moves.length&&m.moves.every(id=>Number.isInteger(id)&&MOVES[id]?.type===SPECIES[m.id].type&&MOVES[id].level<=m.level))));}
export function validBattle(b,s){if(b===null)return !s?.postgame?.tower||s.postgame.tower.waiting;if(b?.effects!==undefined){if(!b.effects||Object.keys(b.effects).some(k=>!['ally','enemy'].includes(k)))return false;for(const side of ['ally','enemy']){const e=b.effects[side];if(!e||Array.isArray(e)||Object.entries(e).some(([k,v])=>!['poison','weaken','focus','shield'].includes(k)||!Number.isInteger(v)||v<0||v>4))return false;}}if(!b||!validState(s)||!Number.isInteger(b.region)||b.region<0||b.region>3||!Number.isInteger(b.active)||!s.party[b.active]||!Number.isInteger(b.turn)||b.turn<0||b.turn>10000||typeof b.boss!=='boolean'||typeof b.final!=='boolean'||typeof b.guard!=='boolean'||!Array.isArray(b.log)||b.log.length>500||b.log.some(x=>typeof x!=='string'||x.length>500)||![null,'win','lose','capture','run'].includes(b.result))return false;if(b.final&&!b.boss)return false;if(b.tower!==undefined&&b.tower!==true)return false;if(b.tower){const run=s.postgame?.tower;if(!b.boss||b.final||!Number.isInteger(b.towerFloor)||b.towerFloor<1||b.towerFloor>999||![null,'win','lose'].includes(b.result))return false;if((b.result===null&&(!run||run.waiting||run.floor!==b.towerFloor))||(b.result==='win'&&(!run||!run.waiting||run.floor!==b.towerFloor))||(b.result==='lose'&&run!==null))return false;}else if(b.towerFloor!==undefined)return false;const monsters=[b.enemy,...(Array.isArray(b.roster)?b.roster:[])];if(!b.enemy||monsters.length>3||monsters.some(m=>!validState({...s,party:[m],box:[]})))return false;if(b.roster!==undefined&&!Array.isArray(b.roster))return false;if(!Number.isInteger(b.totalEnemies)||b.totalEnemies<1||b.totalEnemies>3||monsters.length>b.totalEnemies)return false;return b.boss?b.totalEnemies>1:b.totalEnemies===1&&!b.roster?.length;}
export function tile(x,y){if(x<0||x>=48||y<0||y>=36)return 'wall';if(x===0||y===0||x===47||y===35)return 'tree';if(x===23||x===24||y===17||y===18||(y===8&&x>=11&&x<=23)||(y===12&&x>=24&&x<=39)||(y===28&&x>=12&&x<=39))return 'path';if((x>=5&&x<=11&&y>=5&&y<=11)||(x>=35&&x<=41&&y>=5&&y<=11)||(x>=5&&x<=11&&y>=25&&y<=31)||(x>=35&&x<=41&&y>=25&&y<=31))return 'town';if((x+y*3)%23===0)return 'tree';if((x*7+y*11)%29===0)return 'water';return (x+y)%4===0||((x*3+y)%5===0)?'grass':'ground';}
export function regionAt(x,y){return (x>=24?1:0)+(y>=18?2:0);}
export function canMove(s,x,y){const r=regionAt(x,y);if(r>s.badges.length)return 'gate';const t=tile(x,y);return ['wall','tree','water'].includes(t)?false:true;}
